package main
import("archive/zip";"crypto/sha256";"encoding/hex";"encoding/json";"flag";"fmt";"io";"net";"net/http";"net/url";"os";"path/filepath";"strconv";"strings";"time")
type S struct{Root,Rel string;Port int;Token string}
func readenv(p,k string)string{b,_:=os.ReadFile(p);for _,l:=range strings.Split(string(b),"\n"){x:=strings.SplitN(l,"=",2);if len(x)==2&&x[0]==k{return strings.TrimSpace(x[1])}};return ""}
func (s *S)auth(r *http.Request)bool{return s.Token!=""&&r.Header.Get("X-Hermes-Token")==s.Token}
func js(w http.ResponseWriter,v any){w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(v)}
func readfile(p string)string{b,_:=os.ReadFile(p);return string(b)}
func exists(p string)bool{_,e:=os.Stat(p);return e==nil}
func temp()float64{b,e:=os.ReadFile("/sys/class/power_supply/battery/temp");if e!=nil{return -1};v,_:=strconv.ParseFloat(strings.TrimSpace(string(b)),64);if v>200{v/=10};return v}
func mem()int64{b,_:=os.ReadFile("/proc/meminfo");for _,l:=range strings.Split(string(b),"\n"){if strings.HasPrefix(l,"MemAvailable:"){f:=strings.Fields(l);if len(f)>1{n,_:=strconv.ParseInt(f[1],10,64);return n/1024}}};return -1}
func iface(n string)(string,string){i,e:=net.InterfaceByName(n);if e!=nil{return"DOWN",""};a,_:=i.Addrs();ip:="";for _,x:=range a{if y,ok:=x.(*net.IPNet);ok&&y.IP.To4()!=nil{ip=y.IP.String()}};if ip==""{return"DOWN",""};return"UP",ip}
func (s *S)status(w http.ResponseWriter,r *http.Request){ts,ip:=iface("rndis0");cur:=strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release")));if cur==""{cur="v0.2.0-control-center"};js(w,map[string]any{"service":"HERMES_WORK","control_center":"v1.0.0","release":cur,"temperature_c":temp(),"mem_available_mb":mem(),"tether_state":ts,"tether_ip":ip,"worker_paused":exists(filepath.Join(s.Root,"state","worker_paused")),"safe_mode":exists(filepath.Join(s.Root,"state","safe_mode")),"bridge_enabled":readenv(filepath.Join(s.Rel,"config","work.env"),"BRIDGE_ENABLED")=="1","components":map[string]string{"collector":"READY_V1","dedup":"READY_V1","categorizer":"READY_V1","trend_scoring":"READY_V1","reasoning":"DEFERRED","content_planner":"READY_V1","knowledge":"READY_FOUNDATION","scheduler":"READY_FOUNDATION"}})}
func (s *S)action(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};var q struct{Action string `json:"action"`};json.NewDecoder(r.Body).Decode(&q);st:=filepath.Join(s.Root,"state");switch q.Action{case"pause":os.WriteFile(filepath.Join(st,"worker_paused"),[]byte(time.Now().Format(time.RFC3339)),0600);case"resume":os.Remove(filepath.Join(st,"worker_paused"));os.Remove(filepath.Join(st,"safe_mode"));case"safe_mode":os.WriteFile(filepath.Join(st,"safe_mode"),[]byte("safe_mode"),0600);os.WriteFile(filepath.Join(st,"worker_paused"),[]byte("safe_mode"),0600);case"backup":os.MkdirAll(filepath.Join(s.Root,"backups"),0700);os.WriteFile(filepath.Join(s.Root,"backups","state-"+time.Now().Format("20060102-150405")+".txt"),[]byte("release="+strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release")))+"\n"),0600);case"rollback":p:=strings.TrimSpace(readfile(filepath.Join(s.Root,"previous_release")));if p==""{http.Error(w,"no previous release",409);return};os.WriteFile(filepath.Join(s.Root,"current_release"),[]byte(p+"\n"),0600);default:http.Error(w,"unknown action",400);return};js(w,map[string]any{"ok":true,"action":q.Action})}
func tail(p string,n int)string{b,_:=os.ReadFile(p);a:=strings.Split(string(b),"\n");if len(a)>n{a=a[len(a)-n:]};return strings.Join(a,"\n")}
func (s *S)diag(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};ts,ip:=iface("rndis0");js(w,map[string]any{"time":time.Now().Format(time.RFC3339),"temp_c":temp(),"mem_mb":mem(),"rndis":ts,"rndis_ip":ip,"release":strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release"))),"bootstrap_log_tail":tail(filepath.Join(s.Root,"logs","hermesd.log"),60),"work_log_tail":tail(filepath.Join(s.Root,"logs","workd.log"),60)})}
func copyf(src,dst string)error{in,e:=os.Open(src);if e!=nil{return e};defer in.Close();if e=os.MkdirAll(filepath.Dir(dst),0700);e!=nil{return e};out,e:=os.OpenFile(dst,os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0700);if e!=nil{return e};_,e=io.Copy(out,in);ce:=out.Close();if e!=nil{return e};return ce}
func unzipPayload(bundle,stage string)error{z,e:=zip.OpenReader(bundle);if e!=nil{return e};defer z.Close();for _,f:=range z.File{n:=filepath.Clean(f.Name);if n=="manifest.json"||strings.HasPrefix(n,"payload/"){if strings.Contains(n,".."){return fmt.Errorf("unsafe path")};dst:=filepath.Join(stage,n);if f.FileInfo().IsDir(){os.MkdirAll(dst,0700);continue};rc,e:=f.Open();if e!=nil{return e};if e=os.MkdirAll(filepath.Dir(dst),0700);e!=nil{rc.Close();return e};o,e:=os.OpenFile(dst,os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0700);if e!=nil{rc.Close();return e};_,e=io.Copy(o,rc);o.Close();rc.Close();if e!=nil{return e}}};return nil}
func (s *S)update(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};ch:=readenv(filepath.Join(s.Rel,"config","work.env"),"UPDATE_CHANNEL_URL");if ch==""{http.Error(w,"channel missing",500);return};cl:=&http.Client{Timeout:45*time.Second};resp,e:=cl.Get(ch);if e!=nil{http.Error(w,e.Error(),502);return};defer resp.Body.Close();if resp.StatusCode!=200{http.Error(w,"channel http "+resp.Status,502);return};var m struct{Version,Bundle,Sha256 string};if e=json.NewDecoder(io.LimitReader(resp.Body,65536)).Decode(&m);e!=nil||m.Version==""||m.Bundle==""||len(m.Sha256)!=64{http.Error(w,"invalid channel",502);return};base:=ch[:strings.LastIndex(ch,"/")+1];tmp:=filepath.Join(s.Root,"updates",m.Version+".zip.tmp");os.MkdirAll(filepath.Dir(tmp),0700);br,e:=cl.Get(base+m.Bundle);if e!=nil{http.Error(w,e.Error(),502);return};defer br.Body.Close();if br.StatusCode!=200{http.Error(w,"bundle http "+br.Status,502);return};o,e:=os.Create(tmp);if e!=nil{http.Error(w,e.Error(),500);return};h:=sha256.New();_,e=io.Copy(io.MultiWriter(o,h),io.LimitReader(br.Body,32<<20));o.Close();if e!=nil{os.Remove(tmp);http.Error(w,e.Error(),500);return};got:=hex.EncodeToString(h.Sum(nil));if !strings.EqualFold(got,m.Sha256){os.Remove(tmp);http.Error(w,"sha256 mismatch",409);return};stage:=filepath.Join(s.Root,"releases",".stage-"+m.Version);os.RemoveAll(stage);os.MkdirAll(stage,0700);if e=unzipPayload(tmp,stage);e!=nil{os.RemoveAll(stage);http.Error(w,e.Error(),500);return};if !exists(filepath.Join(stage,"manifest.json"))||!exists(filepath.Join(stage,"payload","bin","workd"))||!exists(filepath.Join(stage,"payload","worker","tick.sh")){os.RemoveAll(stage);http.Error(w,"invalid bundle structure",409);return};dest:=filepath.Join(s.Root,"releases",m.Version);next:=dest+".new";os.RemoveAll(next);os.MkdirAll(next,0700);if e=copyf(filepath.Join(stage,"manifest.json"),filepath.Join(next,"manifest.json"));e!=nil{http.Error(w,e.Error(),500);return};filepath.Walk(filepath.Join(stage,"payload"),func(p string,i os.FileInfo,er error)error{if er!=nil||i.IsDir(){return er};rel,_:=filepath.Rel(filepath.Join(stage,"payload"),p);return copyf(p,filepath.Join(next,rel))});os.Chmod(filepath.Join(next,"bin","workd"),0755);os.Chmod(filepath.Join(next,"worker","tick.sh"),0755);cur:=strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release")));if cur!=""&&cur!=m.Version{os.WriteFile(filepath.Join(s.Root,"previous_release"),[]byte(cur+"\n"),0600)};os.RemoveAll(dest);if e=os.Rename(next,dest);e!=nil{http.Error(w,e.Error(),500);return};os.WriteFile(filepath.Join(s.Root,"current_release"),[]byte(m.Version+"\n"),0600);os.RemoveAll(stage);os.Rename(tmp,filepath.Join(s.Root,"updates",m.Version+".zip"));js(w,map[string]any{"ok":true,"state":"INSTALLED","version":m.Version,"sha256":got,"restart":false,"handoff":"scheduled"});if f,er:=os.OpenFile(filepath.Join(s.Root,"logs","handoff.log"),os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);er==nil{fmt.Fprintln(f,time.Now().Format(time.RFC3339),"handoff",m.Version);f.Close()};go func(){time.Sleep(700*time.Millisecond);p:=filepath.Join(dest,"worker","handoff.sh");if exists(p){os.StartProcess("/system/bin/sh",[]string{"sh",p,s.Root,m.Version,cur},&os.ProcAttr{Files:[]*os.File{nil,nil,nil}})}}()}
func guard(s *S)(bool,string){ts,_:=iface("rndis0");if ts!="UP"{return false,"TETHER_DOWN"};if temp()>=44{return false,"THERMAL_GUARD"};if mem()<220{return false,"LOW_RAM"};if exists(filepath.Join(s.Root,"state","safe_mode"))||exists(filepath.Join(s.Root,"state","worker_paused")){return false,"PAUSED"};return true,"READY"}
func classify(t string)string{x:=strings.ToLower(t);cats:=map[string][]string{"colors":{"color","colour","warna","red","blue","green"},"numbers":{"number","count","angka","counting"},"alphabet":{"alphabet","abc","letter","phonics"},"animals":{"animal","cat","dog","dinosaur","hewan"},"shapes":{"shape","circle","square","bentuk"},"habits":{"habit","brush","wash","sharing","kebiasaan"},"english":{"english","vocabulary","word"},"stories":{"story","stories","tale","cerita"}};for k,ws:=range cats{for _,w:=range ws{if strings.Contains(x,w){return k}}};return "other"}
func (s *S)collect(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};ok,reason:=guard(s);if !ok{js(w,map[string]any{"ok":false,"state":"GUARDED","reason":reason});return};var q struct{Items []struct{Title string `json:"title"`;Source string `json:"source"`;URL string `json:"url"`;Score float64 `json:"score"`} `json:"items"`};if e:=json.NewDecoder(io.LimitReader(r.Body,1<<20)).Decode(&q);e!=nil{http.Error(w,"invalid json",400);return};dir:=filepath.Join(s.Root,"data","database");os.MkdirAll(dir,0700);p:=filepath.Join(dir,"research.jsonl");seen:=map[string]bool{};if b,e:=os.ReadFile(p);e==nil{for _,l:=range strings.Split(string(b),"\n"){var z map[string]any;if json.Unmarshal([]byte(l),&z)==nil{if u,_:=z["url"].(string);u!=""{seen[u]=true}}}};f,e:=os.OpenFile(p,os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);if e!=nil{http.Error(w,e.Error(),500);return};defer f.Close();added,dup:=0,0;enc:=json.NewEncoder(f);for _,it:=range q.Items{if it.URL!=""&&seen[it.URL]{dup++;continue};cat:=classify(it.Title);score:=it.Score;if score==0{score=50};enc.Encode(map[string]any{"ts":time.Now().Format(time.RFC3339),"title":it.Title,"source":it.Source,"url":it.URL,"category":cat,"score":score});if it.URL!=""{seen[it.URL]=true};added++};os.WriteFile(filepath.Join(s.Root,"state","last_research"),[]byte(time.Now().Format(time.RFC3339)),0600);js(w,map[string]any{"ok":true,"state":"COLLECTED","received":len(q.Items),"added":added,"duplicates":dup})}
func (s *S)research(w http.ResponseWriter,r *http.Request){b,_:=os.ReadFile(filepath.Join(s.Root,"data","database","research.jsonl"));lines:=strings.Split(strings.TrimSpace(string(b)),"\n");cats:=map[string]int{};total:=0;for _,l:=range lines{if strings.TrimSpace(l)==""{continue};var z map[string]any;if json.Unmarshal([]byte(l),&z)==nil{total++;if x,ok:=z["category"].(string);ok{cats[x]++}}};js(w,map[string]any{"total_items":total,"categories":cats,"last_research":strings.TrimSpace(readfile(filepath.Join(s.Root,"state","last_research")))})}
type AutoItem struct{Title,Source,URL string;Score float64}
func (s *S)storeAuto(items []AutoItem)(int,int,error){dir:=filepath.Join(s.Root,"data","database");os.MkdirAll(dir,0700);p:=filepath.Join(dir,"research.jsonl");seen:=map[string]bool{};if b,e:=os.ReadFile(p);e==nil{for _,l:=range strings.Split(string(b),"\n"){var z map[string]any;if json.Unmarshal([]byte(l),&z)==nil{if u,_:=z["url"].(string);u!=""{seen[u]=true}}}};f,e:=os.OpenFile(p,os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);if e!=nil{return 0,0,e};defer f.Close();enc:=json.NewEncoder(f);added,dup:=0,0;for _,it:=range items{if it.URL!=""&&seen[it.URL]{dup++;continue};enc.Encode(map[string]any{"ts":time.Now().Format(time.RFC3339),"title":it.Title,"source":it.Source,"url":it.URL,"category":classify(it.Title),"score":it.Score});if it.URL!=""{seen[it.URL]=true};added++};os.WriteFile(filepath.Join(s.Root,"state","last_research"),[]byte(time.Now().Format(time.RFC3339)),0600);return added,dup,nil}
func ytSuggest(q string)([]string,error){u:="https://suggestqueries.google.com/complete/search?client=firefox&ds=yt&q="+url.QueryEscape(q);cl:=&http.Client{Timeout:12*time.Second};r,e:=cl.Get(u);if e!=nil{return nil,e};defer r.Body.Close();if r.StatusCode!=200{return nil,fmt.Errorf("suggest http %s",r.Status)};var v []any;if e=json.NewDecoder(io.LimitReader(r.Body,1<<20)).Decode(&v);e!=nil{return nil,e};if len(v)<2{return nil,fmt.Errorf("bad suggest response")};a,ok:=v[1].([]any);if !ok{return nil,fmt.Errorf("bad suggestions")};var out []string;for _,x:=range a{if s,ok:=x.(string);ok&&strings.TrimSpace(s)!=""{out=append(out,strings.TrimSpace(s))}};return out,nil}
func (s *S)autoResearch()(map[string]any,error){ok,reason:=guard(s);if !ok{return map[string]any{"ok":false,"state":"GUARDED","reason":reason},nil};seeds:=[]string{"learn colors for kids","learn numbers for kids","alphabet for kids","animals for kids","shapes for kids","good habits for kids","english words for kids","short stories for kids","belajar warna anak","belajar angka anak","alfabet anak","nama hewan anak","bentuk untuk anak","kebiasaan baik anak","bahasa inggris anak"};agg:=map[string]struct{Count,Best int}{};checked:=0;for _,q:=range seeds{ss,e:=ytSuggest(q);if e!=nil{continue};checked++;for i,t:=range ss{z:=agg[t];z.Count++;if z.Best==0||i+1<z.Best{z.Best=i+1};agg[t]=z};time.Sleep(120*time.Millisecond)};var items []AutoItem;for t,z:=range agg{sc:=50+float64(z.Count*8)+float64(12-z.Best*2);if sc>100{sc=100};items=append(items,AutoItem{Title:t,Source:"youtube_autocomplete",URL:"ytsearch:"+strings.ReplaceAll(strings.ToLower(t)," ","+"),Score:sc})};added,dup,e:=s.storeAuto(items);if e!=nil{return nil,e};res:=map[string]any{"ok":true,"state":"RESEARCHED","sources_checked":checked,"found":len(items),"added":added,"duplicates":dup};b,_:=json.Marshal(res);os.WriteFile(filepath.Join(s.Root,"state","last_research_result.json"),b,0600);return res,nil}
func (s *S)runResearch(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};res,e:=s.autoResearch();if e!=nil{http.Error(w,e.Error(),502);return};js(w,res)}
func (s *S)schedulerLoop(){for{cfg:=readenv(filepath.Join(s.Rel,"config","work.env"),"RESEARCH_SCHEDULE");if cfg==""{cfg="08:00"};now:=time.Now();day:=now.Format("2006-01-02");last:=strings.TrimSpace(readfile(filepath.Join(s.Root,"state","last_auto_research_date")));if now.Format("15:04")==cfg&&last!=day{if ok,_:=guard(s);ok{if _,e:=s.autoResearch();e==nil{os.WriteFile(filepath.Join(s.Root,"state","last_auto_research_date"),[]byte(day),0600)}}};time.Sleep(30*time.Second)}}
func (s *S)brief(w http.ResponseWriter,r *http.Request){b,_:=os.ReadFile(filepath.Join(s.Root,"data","database","research.jsonl"));type item struct{Title,Category,URL string;Score float64};var a []item;for _,l:=range strings.Split(strings.TrimSpace(string(b)),"\n"){if l==""{continue};var z map[string]any;if json.Unmarshal([]byte(l),&z)!=nil{continue};it:=item{};it.Title,_=z["title"].(string);it.Category,_=z["category"].(string);it.URL,_=z["url"].(string);it.Score,_=z["score"].(float64);a=append(a,it)};for i:=0;i<len(a);i++{for j:=i+1;j<len(a);j++{if a[j].Score>a[i].Score{a[i],a[j]=a[j],a[i]}}};if len(a)>10{a=a[:10]};js(w,map[string]any{"generated_at":time.Now().Format(time.RFC3339),"target_age":"3-6","ideas":a})}
func (s *S)schedule(w http.ResponseWriter,r *http.Request){ok,reason:=guard(s);next:=readenv(filepath.Join(s.Rel,"config","work.env"),"RESEARCH_SCHEDULE");js(w,map[string]any{"enabled":true,"schedule":next,"guard_ready":ok,"guard_reason":reason,"last_research":strings.TrimSpace(readfile(filepath.Join(s.Root,"state","last_research")))})}
func (s *S)index(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");io.WriteString(w,page)}
func main(){root:=flag.String("root","/data/adb/hermes_work","");rel:=flag.String("release","","");flag.Parse();p:=8766;if x:=readenv(filepath.Join(*rel,"config","work.env"),"WORK_PORT");x!=""{p,_=strconv.Atoi(x)};s:=&S{Root:*root,Rel:*rel,Port:p,Token:readenv(filepath.Join(*root,"config.env"),"ADMIN_TOKEN")};m:=http.NewServeMux();m.HandleFunc("/",s.index);m.HandleFunc("/api/work/status",s.status);m.HandleFunc("/api/work/action",s.action);m.HandleFunc("/api/work/diagnostics",s.diag);m.HandleFunc("/api/work/update",s.update);m.HandleFunc("/api/work/collect",s.collect);m.HandleFunc("/api/work/research",s.research);m.HandleFunc("/api/work/brief",s.brief);m.HandleFunc("/api/work/schedule",s.schedule);m.HandleFunc("/api/work/run-research",s.runResearch);go s.schedulerLoop();http.ListenAndServe(fmt.Sprintf("0.0.0.0:%d",p),m)}
const page=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HERMES WORK</title><style>body{margin:0;background:#0d1117;color:#e6edf3;font:14px system-ui}main{max-width:1050px;margin:auto;padding:18px}.card{padding:16px;margin:12px 0;border:1px solid #30363d;background:#161b22;border-radius:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.box{background:#0d1117;border:1px solid #30363d;border-radius:11px;padding:12px}.k{font-size:11px;color:#8b949e}.v{font-size:18px;font-weight:700}.ok{color:#3fb950}.warn{color:#d29922}button,input{background:#21262d;color:#e6edf3;border:1px solid #30363d;border-radius:9px;padding:10px;margin:4px}.primary{background:#238636}pre{white-space:pre-wrap;background:#010409;padding:12px;border-radius:10px}</style></head><body><main><h2>HERMES WORK <span id="online">CONNECTING</span></h2><p>Digital Work Control Center · Redmi 5A</p><div class="card"><div class="grid"><div class="box"><div class="k">MODEM</div><div id="tether" class="v">-</div></div><div class="box"><div class="k">TEMP</div><div id="temp" class="v">-</div></div><div class="box"><div class="k">FREE RAM</div><div id="ram" class="v">-</div></div><div class="box"><div class="k">WORKER</div><div id="worker" class="v">-</div></div><div class="box"><div class="k">RELEASE</div><div id="release" class="v">-</div></div></div></div><div class="card"><h3>Today&apos;s Work</h3><button class="primary" id="research">RUN RESEARCH NOW</button><pre id="researchout">Research ready.</pre></div><div class="card"><h3>Work Pipeline</h3><p>Research → Dedup → Categorize → Trend Score → Content Brief → Production → Feedback</p><div id="components" class="grid"></div></div><div class="card"><h3>Update & Recovery</h3><input id="token" type="password" placeholder="Admin token"><button class="primary" id="update">CHECK / UPDATE NOW</button><button id="backup">BACKUP</button><button id="safe">SAFE MODE</button><button id="resume">RESUME</button><button id="rollback">ROLLBACK</button><button id="diag">DIAGNOSTICS</button><pre id="out">Ready.</pre></div><div class="card"><h3>ChatGPT / HERMES Bridge</h3><p>Bridge foundation ready. Root terminal remains LAN-only.</p></div></main><script>const $=x=>document.getElementById(x);function h(){return {'X-Hermes-Token':$('token').value.trim(),'Content-Type':'application/json'}}async function st(){try{let j=await(await fetch('/api/work/status')).json();$('online').textContent='● ONLINE';$('tether').textContent=j.tether_state+' '+j.tether_ip;$('temp').textContent=j.temperature_c.toFixed(1)+' °C';$('ram').textContent=j.mem_available_mb+' MB';$('worker').textContent=j.safe_mode?'SAFE MODE':(j.worker_paused?'PAUSED':'READY');$('release').textContent=j.release;$('components').innerHTML=Object.entries(j.components).map(([k,v])=>'<div class="box"><div class="k">'+k.toUpperCase()+'</div><div class="v '+(v.includes('NOT')?'warn':'')+'">'+v+'</div></div>').join('')}catch(e){$('online').textContent='● OFFLINE'}}async function act(a){let r=await fetch('/api/work/action',{method:'POST',headers:h(),body:JSON.stringify({action:a})});$('out').textContent=await r.text();st()}$('backup').onclick=()=>act('backup');$('safe').onclick=()=>act('safe_mode');$('resume').onclick=()=>act('resume');$('rollback').onclick=()=>act('rollback');$('diag').onclick=async()=>{$('out').textContent=await(await fetch('/api/work/diagnostics',{headers:h()})).text()};$('research').onclick=async()=>{$('researchout').textContent='Running research...';$('researchout').textContent=await(await fetch('/api/work/run-research',{method:'POST',headers:h()})).text();st()};$('update').onclick=async()=>{$('out').textContent=await(await fetch('/api/work/update',{method:'POST',headers:h()})).text()};st();setInterval(st,5000)</script></body></html>`